1	/**
2	 * Hilo University Routes — In-platform learning hub.
3	 *
4	 * Flight school side (requireAuth): read-only consumption of published content
5	 * and per-user progress tracking.
6	 *
7	 * Admin side (requireSuperAdmin): full CRUD for categories, lessons,
8	 * attachments, tags, and reordering.
9	 */
10	
11	import { getAnthropicKey } from '@/lib/anthropic/api-key';
12	import { db } from '@/lib/db';
13	import { formatErrorForUser } from '@/lib/errors/format-error-for-user';
14	import { ANTHROPIC_MODEL } from '@/lib/orchestrator/config';
15	import * as schema from '@/lib/schema';
16	import { requireAuth, requireSuperAdmin } from '@/server/middleware/auth';
17	import type { AuthUser } from '@/server/middleware/auth';
18	import { resolveProfilePhotoUrl } from '@/server/utils/s3';
19	import {
20	  and,
21	  asc,
22	  count,
23	  desc,
24	  eq,
25	  ilike,
26	  inArray,
27	  or,
28	  sql,
29	} from 'drizzle-orm';
30	import { Hono } from 'hono';
31	import { videoRenders } from '../../../packages/video/src/db/schema';
32	
33	// ─── Role filter helper ──────────────────────────────────────────────────────
34	// Hilo University role tags use the team-role values from the userRoleEnum
35	// (`student | instructor | admin | mechanic`) plus the `global` sentinel.
36	// `super_admin` is a Better Auth platform role and bypasses the filter.
37	const HU_LEARNER_ROLES = [
38	  'student',
39	  'instructor',
40	  'admin',
41	  'mechanic',
42	] as const;
43	
44	interface LearnerContext {
45	  /**
46	   * The application `users.id` (uuid) for the caller, or `null` when the
47	   * authenticated session has no Hilo `users` row (e.g. super_admins). Better
48	   * Auth `user.id` is a CUID2 text value that does NOT match this column —
49	   * comparing `users.id` to `authUser.id` directly throws 22P02. Always look
50	   * up the Hilo id by email here so downstream `eq(<uuid col>, ctx.userId)`
51	   * predicates are type-correct.
52	   */
53	  userId: string | null;
54	  flightSchoolId: string | null;
55	  teamRole: string | null;
56	  isSuperAdmin: boolean;
57	}
58	
59	/**
60	 * Resolve the caller's Hilo `users.id` (uuid), flight school, and team role
61	 * in a single DB lookup keyed by email. Super admins bypass the role filter
62	 * entirely and may not have an app users row; for them every field below
63	 * `isSuperAdmin` is nullable.
64	 */
65	async function resolveLearnerContext(
66	  authUser: AuthUser,
67	): Promise<LearnerContext> {
68	  const isSuperAdmin = authUser.role === 'super_admin';
69	  const [row] = await db
70	    .select({
71	      id: schema.users.id,
72	      flightSchoolId: schema.users.flightSchoolId,
73	      teamRole: schema.users.role,
74	    })
75	    .from(schema.users)
76	    .where(eq(schema.users.email, authUser.email))
77	    .limit(1);
78	  return {
79	    userId: row?.id ?? null,
80	    flightSchoolId: row?.flightSchoolId ?? null,
81	    teamRole: row?.teamRole ?? null,
82	    isSuperAdmin,
83	  };
84	}
85	
86	/**
87	 * Lesson visibility predicate. Super admins see everything; other roles see
88	 * published lessons tagged with their team role OR `global`. Untagged lessons
89	 * (`roles []`) are visible to no non-super-admin caller.
90	 */
91	function lessonRoleVisibility(
92	  ctx: LearnerContext,
93	): ReturnType<typeof sql> | undefined {
94	  if (ctx.isSuperAdmin) return undefined;
95	  if (!ctx.teamRole) {
96	    // Authenticated but no team role: hide all role-tagged lessons.
97	    return sql`${schema.hiloUniversityLessons.roles} @> '["global"]'::jsonb`;
98	  }
99	  const roleJson = JSON.stringify([ctx.teamRole]);
100	  return sql`(${schema.hiloUniversityLessons.roles} @> ${roleJson}::jsonb OR ${schema.hiloUniversityLessons.roles} @> '["global"]'::jsonb)`;
101	}
102	
103	export const hiloUniversityRoutes = new Hono<{
104	  Variables: { authUser?: AuthUser };
105	}>();
106	
107	// ─── Loom Utilities ───────────────────────────────────────────────────────────
108	
109	function normalizeLoomUrl(
110	  url: string,
111	): { embedUrl: string; videoId: string } | null {
112	  try {
113	    const u = new URL(url.startsWith('http') ? url : `https://${url}`);
114	    if (!u.hostname.includes('loom.com')) return null;
115	    const parts = u.pathname.split('/').filter(Boolean);
116	    const id = parts[parts.length - 1];
117	    if (!id) return null;
118	    return { embedUrl: `https://www.loom.com/embed/${id}`, videoId: id };
119	  } catch {
120	    return null;
121	  }
122	}
123	
124	async function fetchLoomOEmbed(
125	  videoUrl: string,
126	): Promise<{ thumbnail: string | null; durationSeconds: number | null }> {
127	  try {
128	    const oembedUrl = `https://www.loom.com/v1/oembed?url=${encodeURIComponent(videoUrl)}`;
129	    const res = await fetch(oembedUrl, { signal: AbortSignal.timeout(5000) });
130	    if (!res.ok) return { thumbnail: null, durationSeconds: null };
131	    const data = (await res.json()) as {
132	      thumbnail_url?: string;
133	      duration?: number;
134	    };
135	    return {
136	      thumbnail: data.thumbnail_url ?? null,
137	      durationSeconds:
138	        typeof data.duration === 'number' ? Math.round(data.duration) : null,
139	    };
140	  } catch {
141	    return { thumbnail: null, durationSeconds: null };
142	  }
143	}
144	
145	// ─── Flight School — Read-Only Endpoints ─────────────────────────────────────
146	
147	/**
148	 * List all visible categories with per-user completion counts.
149	 *
150	 * Visibility rule:
151	 * - Published categories are always visible.
152	 * - Draft categories become visible when they contain at least one published
153	 *   lesson (data-drift tolerance for legacy content states).
154	 */
155	hiloUniversityRoutes.get(
156	  '/hilo-university/categories',
157	  requireAuth(),
158	  async (c) => {
159	    const authUser = c.get('authUser') as AuthUser;
160	    try {
161	      const ctx = await resolveLearnerContext(authUser);
162	      const visibility = lessonRoleVisibility(ctx);
163	
164	      const cats = await db
165	        .select()
166	        .from(schema.hiloUniversityCategories)
167	        .orderBy(asc(schema.hiloUniversityCategories.sortOrder));
168	
169	      // For each category fetch role-visible published lessons and the
170	      // caller's completed count (org-scoped via flight_school_id).
171	      const categoriesWithProgress = await Promise.all(
172	        cats.map(async (cat) => {
173	          const lessonClauses = [
174	            eq(schema.hiloUniversityLessons.categoryId, cat.id),
175	            eq(schema.hiloUniversityLessons.status, 'published'),
176	          ];
177	          if (visibility) lessonClauses.push(visibility);
178	
179	          const lessons = await db
180	            .select({ id: schema.hiloUniversityLessons.id })
181	            .from(schema.hiloUniversityLessons)
182	            .where(and(...lessonClauses));
183	
184	          const lessonIds = lessons.map((l) => l.id);
185	          let completedCount = 0;
186	          if (lessonIds.length > 0 && ctx.flightSchoolId && ctx.userId) {
187	            const progress = await db
188	              .select({
189	                lessonId: schema.hiloUniversityLessonProgress.lessonId,
190	              })
191	              .from(schema.hiloUniversityLessonProgress)
192	              .where(
193	                and(
194	                  eq(schema.hiloUniversityLessonProgress.userId, ctx.userId),
195	                  eq(
196	                    schema.hiloUniversityLessonProgress.flightSchoolId,
197	                    ctx.flightSchoolId,
198	                  ),
199	                  eq(schema.hiloUniversityLessonProgress.status, 'completed'),
200	                  inArray(
201	                    schema.hiloUniversityLessonProgress.lessonId,
202	                    lessonIds,
203	                  ),
204	                ),
205	              );
206	            completedCount = progress.length;
207	          }
208	
209	          return {
210	            ...cat,
211	            thumbnailUrl: await resolveProfilePhotoUrl(cat.thumbnailUrl),
212	            totalLessons: lessonIds.length,
213	            completedLessons: completedCount,
214	          };
215	        }),
216	      );
217	
218	      const visibleCategories = categoriesWithProgress.filter(
219	        (cat) => cat.isPublished || cat.totalLessons > 0,
220	      );
221	
222	      return c.json({ categories: visibleCategories });
223	    } catch (err) {
224	      const structured = formatErrorForUser(err, {
225	        feature: 'HILU',
226	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
227	      });
228	      return c.json(
229	        {
230	          error: structured.message,
231	          reference_id: structured.reference_id,
232	          retry_safe: structured.retry_safe,
233	        },
234	        500,
235	      );
236	    }
237	  },
238	);
239	
240	/**
241	 * List published lessons for a category with per-lesson completion status.
242	 *
243	 * Tolerates legacy drift where a category is still draft but one or more
244	 * lessons are published. In that case, the category/lessons are still visible.
245	 */
246	hiloUniversityRoutes.get(
247	  '/hilo-university/categories/:categoryId/lessons',
248	  requireAuth(),
249	  async (c) => {
250	    const authUser = c.get('authUser') as AuthUser;
251	    const { categoryId } = c.req.param();
252	    try {
253	      const [category] = await db
254	        .select()
255	        .from(schema.hiloUniversityCategories)
256	        .where(eq(schema.hiloUniversityCategories.id, categoryId))
257	        .limit(1);
258	
259	      if (!category) {
260	        return c.json({ error: 'Category not found' }, 404);
261	      }
262	
263	      const lessons = await db
264	        .select()
265	        .from(schema.hiloUniversityLessons)
266	        .where(
267	          and(
268	            eq(schema.hiloUniversityLessons.categoryId, categoryId),
269	            eq(schema.hiloUniversityLessons.isPublished, true),
270	          ),
271	        )
272	        .orderBy(asc(schema.hiloUniversityLessons.sortOrder));
273	
274	      // Fetch completion status for each lesson. Look the caller's Hilo
275	      // users.id (uuid) up by email — authUser.id is a Better Auth CUID that
276	      // would fail to cast to uuid when used as a predicate value.
277	      const ctx = await resolveLearnerContext(authUser);
278	      const lessonIds = lessons.map((l) => l.id);
279	      const progress =
280	        lessonIds.length > 0 && ctx.userId
281	          ? await db
282	              .select()
283	              .from(schema.hiloUniversityLessonProgress)
284	              .where(
285	                and(
286	                  eq(schema.hiloUniversityLessonProgress.userId, ctx.userId),
287	                  inArray(
288	                    schema.hiloUniversityLessonProgress.lessonId,
289	                    lessonIds,
290	                  ),
291	                ),
292	              )
293	          : [];
294	      const completedIds = new Set(progress.map((p) => p.lessonId));
295	
296	      const lessonsWithStatus = lessons.map((l) => ({
297	        ...l,
298	        completed: completedIds.has(l.id),
299	      }));
300	
301	      if (!category.isPublished && lessonsWithStatus.length === 0) {
302	        return c.json({ error: 'Category not found' }, 404);
303	      }
304	
305	      return c.json({
306	        category: {
307	          ...category,
308	          thumbnailUrl: await resolveProfilePhotoUrl(category.thumbnailUrl),
309	          totalLessons: lessons.length,
310	          completedLessons: completedIds.size,
311	        },
312	        lessons: lessonsWithStatus,
313	      });
314	    } catch (err) {
315	      const structured = formatErrorForUser(err, {
316	        feature: 'HILU',
317	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
318	      });
319	      return c.json(
320	        {
321	          error: structured.message,
322	          reference_id: structured.reference_id,
323	          retry_safe: structured.retry_safe,
324	        },
325	        500,
326	      );
327	    }
328	  },
329	);
