331	/** Get a single lesson with attachments, prev/next navigation, and completion status. */
332	hiloUniversityRoutes.get(
333	  '/hilo-university/lessons/:lessonId',
334	  requireAuth(),
335	  async (c) => {
336	    const authUser = c.get('authUser') as AuthUser;
337	    const { lessonId } = c.req.param();
338	    try {
339	      const [lesson] = await db
340	        .select()
341	        .from(schema.hiloUniversityLessons)
342	        .where(
343	          and(
344	            eq(schema.hiloUniversityLessons.id, lessonId),
345	            eq(schema.hiloUniversityLessons.isPublished, true),
346	          ),
347	        )
348	        .limit(1);
349	
350	      if (!lesson) return c.json({ error: 'Lesson not found' }, 404);
351	
352	      const [category] = await db
353	        .select()
354	        .from(schema.hiloUniversityCategories)
355	        .where(eq(schema.hiloUniversityCategories.id, lesson.categoryId))
356	        .limit(1);
357	
358	      const attachments = await db
359	        .select()
360	        .from(schema.hiloUniversityLessonAttachments)
361	        .where(eq(schema.hiloUniversityLessonAttachments.lessonId, lessonId))
362	        .orderBy(asc(schema.hiloUniversityLessonAttachments.sortOrder));
363	
364	      // Look the caller's Hilo users.id (uuid) up by email — authUser.id is
365	      // a Better Auth CUID that would fail to cast to uuid in the predicate.
366	      const ctx = await resolveLearnerContext(authUser);
367	      const [progressRow] = ctx.userId
368	        ? await db
369	            .select()
370	            .from(schema.hiloUniversityLessonProgress)
371	            .where(
372	              and(
373	                eq(schema.hiloUniversityLessonProgress.userId, ctx.userId),
374	                eq(schema.hiloUniversityLessonProgress.lessonId, lessonId),
375	              ),
376	            )
377	            .limit(1)
378	        : [];
379	
380	      // Fetch sibling lessons for prev/next navigation
381	      const siblings = await db
382	        .select({
383	          id: schema.hiloUniversityLessons.id,
384	          title: schema.hiloUniversityLessons.title,
385	          sortOrder: schema.hiloUniversityLessons.sortOrder,
386	        })
387	        .from(schema.hiloUniversityLessons)
388	        .where(
389	          and(
390	            eq(schema.hiloUniversityLessons.categoryId, lesson.categoryId),
391	            eq(schema.hiloUniversityLessons.isPublished, true),
392	          ),
393	        )
394	        .orderBy(asc(schema.hiloUniversityLessons.sortOrder));
395	
396	      const idx = siblings.findIndex((s) => s.id === lessonId);
397	      const prevLesson = idx > 0 ? siblings[idx - 1] : null;
398	      const nextLesson = idx < siblings.length - 1 ? siblings[idx + 1] : null;
399	
400	      // Look up latest non-superseded tutorial render for this lesson
401	      const [latestRender] = await db
402	        .select({ id: videoRenders.id, status: videoRenders.status })
403	        .from(videoRenders)
404	        .where(
405	          and(
406	            eq(videoRenders.videoType, 'tutorial'),
407	            eq(videoRenders.sourceEntityId, lessonId),
408	            eq(videoRenders.superseded, false),
409	          ),
410	        )
411	        .orderBy(desc(videoRenders.createdAt))
412	        .limit(1);
413	
414	      return c.json({
415	        lesson: { ...lesson, completed: !!progressRow },
416	        category,
417	        attachments,
418	        completed: !!progressRow,
419	        completedAt: progressRow?.completedAt?.toISOString() ?? null,
420	        prevLesson,
421	        nextLesson,
422	        renderId: latestRender?.id ?? null,
423	        renderStatus: latestRender?.status ?? null,
424	      });
425	    } catch (err) {
426	      const structured = formatErrorForUser(err, {
427	        feature: 'HILU',
428	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
429	      });
430	      return c.json(
431	        {
432	          error: structured.message,
433	          reference_id: structured.reference_id,
434	          retry_safe: structured.retry_safe,
435	        },
436	        500,
437	      );
438	    }
439	  },
440	);
