442	/** Mark lesson complete (upsert). */
443	hiloUniversityRoutes.post(
444	  '/hilo-university/lessons/:lessonId/complete',
445	  requireAuth(),
446	  async (c) => {
447	    const authUser = c.get('authUser') as AuthUser;
448	    const { lessonId } = c.req.param();
449	    try {
450	      // Wave 1 schema landing: flight_school_id is now NOT NULL on
451	      // hilo_university_lesson_progress. Wave 2's w2-a2-learner will
452	      // overhaul this endpoint to honor full v1 progress semantics
453	      // (step/task completion, percent_complete, last_step_id).
454	      const ctx = await resolveLearnerContext(authUser);
455	      if (!ctx.userId || !ctx.flightSchoolId) {
456	        return c.json({ error: 'User missing flight school' }, 400);
457	      }
458	      await db
459	        .insert(schema.hiloUniversityLessonProgress)
460	        .values({
461	          userId: ctx.userId,
462	          flightSchoolId: ctx.flightSchoolId,
463	          lessonId,
464	        })
465	        .onConflictDoNothing();
466	      return c.json({ ok: true });
467	    } catch (err) {
468	      const structured = formatErrorForUser(err, {
469	        feature: 'HILU',
470	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
471	      });
472	      return c.json(
473	        {
474	          error: structured.message,
475	          reference_id: structured.reference_id,
476	          retry_safe: structured.retry_safe,
477	        },
478	        500,
479	      );
480	    }
481	  },
482	);
483	
484	/** Unmark lesson complete. */
485	hiloUniversityRoutes.delete(
486	  '/hilo-university/lessons/:lessonId/complete',
487	  requireAuth(),
488	  async (c) => {
489	    const authUser = c.get('authUser') as AuthUser;
490	    const { lessonId } = c.req.param();
491	    try {
492	      const ctx = await resolveLearnerContext(authUser);
493	      if (!ctx.userId) {
494	        return c.json({ ok: true });
495	      }
496	      await db
497	        .delete(schema.hiloUniversityLessonProgress)
498	        .where(
499	          and(
500	            eq(schema.hiloUniversityLessonProgress.userId, ctx.userId),
501	            eq(schema.hiloUniversityLessonProgress.lessonId, lessonId),
502	          ),
503	        );
504	      return c.json({ ok: true });
505	    } catch (err) {
506	      const structured = formatErrorForUser(err, {
507	        feature: 'HILU',
508	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
509	      });
510	      return c.json(
511	        {
512	          error: structured.message,
513	          reference_id: structured.reference_id,
514	          retry_safe: structured.retry_safe,
515	        },
516	        500,
517	      );
518	    }
519	  },
520	);
