522	/** Get overall progress for the logged-in user. */
523	hiloUniversityRoutes.get(
524	  '/hilo-university/progress',
525	  requireAuth(),
526	  async (c) => {
527	    const authUser = c.get('authUser') as AuthUser;
528	    try {
529	      const [totalRow] = await db
530	        .select({ count: count() })
531	        .from(schema.hiloUniversityLessons)
532	        .where(eq(schema.hiloUniversityLessons.isPublished, true));
533	
534	      const ctx = await resolveLearnerContext(authUser);
535	      const completedRows = ctx.userId
536	        ? await db
537	            .select()
538	            .from(schema.hiloUniversityLessonProgress)
539	            .where(eq(schema.hiloUniversityLessonProgress.userId, ctx.userId))
540	        : [];
541	
542	      return c.json({
543	        totalLessons: totalRow?.count ?? 0,
544	        completedLessons: completedRows.length,
545	      });
546	    } catch (err) {
547	      const structured = formatErrorForUser(err, {
548	        feature: 'HILU',
549	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
550	      });
551	      return c.json(
552	        {
553	          error: structured.message,
554	          reference_id: structured.reference_id,
555	          retry_safe: structured.retry_safe,
556	        },
557	        500,
558	      );
559	    }
