563	/** Full-text search across published categories and lessons. */
564	hiloUniversityRoutes.get(
565	  '/hilo-university/search',
566	  requireAuth(),
567	  async (c) => {
568	    const q = c.req.query('q')?.trim() ?? '';
569	    if (!q) return c.json({ results: [] });
570	    try {
571	      const lessonMatches = await db
572	        .select({
573	          lessonId: schema.hiloUniversityLessons.id,
574	          lessonTitle: schema.hiloUniversityLessons.title,
575	          lessonDescription: schema.hiloUniversityLessons.description,
576	          categoryId: schema.hiloUniversityCategories.id,
577	          categoryTitle: schema.hiloUniversityCategories.title,
578	        })
579	        .from(schema.hiloUniversityLessons)
580	        .innerJoin(
581	          schema.hiloUniversityCategories,
582	          eq(
583	            schema.hiloUniversityLessons.categoryId,
584	            schema.hiloUniversityCategories.id,
585	          ),
586	        )
587	        .where(
588	          and(
589	            eq(schema.hiloUniversityLessons.isPublished, true),
590	            eq(schema.hiloUniversityCategories.isPublished, true),
591	            or(
592	              ilike(schema.hiloUniversityLessons.title, `%${q}%`),
593	              ilike(schema.hiloUniversityLessons.description, `%${q}%`),
594	              ilike(schema.hiloUniversityCategories.title, `%${q}%`),
595	            ),
596	          ),
597	        )
598	        .orderBy(asc(schema.hiloUniversityCategories.sortOrder))
599	        .limit(30);
600	
601	      return c.json({ results: lessonMatches });
602	    } catch (err) {
603	      const structured = formatErrorForUser(err, {
604	        feature: 'HILU',
605	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
606	      });
607	      return c.json(
608	        {
609	          error: structured.message,
610	          reference_id: structured.reference_id,
611	          retry_safe: structured.retry_safe,
612	        },
613	        500,
614	      );
615	    }
616	  },
617	);
