619	// ─── Learner v2 — Full lesson hydration + step/task progress ─────────────────
620	
621	/**
622	 * Full lesson payload for the learner viewer: lesson row, category, goals,
623	 * tasks with nested steps (sort-ordered), the caller's progress, and
624	 * assignment status. Content reads are NOT scoped by flight_school_id;
625	 * progress, completions and assignments ARE scoped to
626	 * `(authUser.id, authUser.flightSchoolId)` per technical-spec §2.3.
627	 */
628	hiloUniversityRoutes.get(
629	  '/hilo-university/lessons/:lessonId/full',
630	  requireAuth(),
631	  async (c) => {
632	    const authUser = c.get('authUser') as AuthUser;
633	    const { lessonId } = c.req.param();
634	    try {
635	      const ctx = await resolveLearnerContext(authUser);
636	
637	      const lessonClauses = [eq(schema.hiloUniversityLessons.id, lessonId)];
638	      if (!ctx.isSuperAdmin) {
639	        lessonClauses.push(
640	          eq(schema.hiloUniversityLessons.status, 'published'),
641	        );
642	        const visibility = lessonRoleVisibility(ctx);
643	        if (visibility) lessonClauses.push(visibility);
644	      }
645	
646	      const [lesson] = await db
647	        .select()
648	        .from(schema.hiloUniversityLessons)
649	        .where(and(...lessonClauses))
650	        .limit(1);
651	
652	      if (!lesson) return c.json({ error: 'Lesson not found' }, 404);
653	
654	      const [category] = await db
655	        .select()
656	        .from(schema.hiloUniversityCategories)
