830	/**
831	 * Idempotent step completion. Single transaction:
832	 *   1. Insert into lesson_step_completions ON CONFLICT DO NOTHING.
833	 *   2. If all steps for the parent task are now complete, insert task
834	 *      completion ON CONFLICT DO NOTHING.
835	 *   3. Recompute the parent lesson's percent_complete and last_step_id;
836	 *      upsert the progress row. status flips to 'completed' at 100%.
837	 * Every read AND write scopes by flight_school_id. No prerequisite gate.
838	 */
839	hiloUniversityRoutes.post(
840	  '/hilo-university/steps/:stepId/complete',
841	  requireAuth(),
842	  async (c) => {
843	    const authUser = c.get('authUser') as AuthUser;
844	    const { stepId } = c.req.param();
845	    try {
846	      const ctx = await resolveLearnerContext(authUser);
847	      if (!ctx.flightSchoolId || !ctx.userId) {
848	        return c.json({ error: 'User missing flight school' }, 400);
849	      }
850	      const flightSchoolId = ctx.flightSchoolId;
851	      const userId = ctx.userId;
852	
853	      const [stepWithLesson] = await db
854	        .select({
855	          stepId: schema.hiloUniversityTaskSteps.id,
856	          taskId: schema.hiloUniversityTaskSteps.taskId,
857	          lessonId: schema.hiloUniversityLessonTasks.lessonId,
858	        })
859	        .from(schema.hiloUniversityTaskSteps)
860	        .innerJoin(
861	          schema.hiloUniversityLessonTasks,
862	          eq(
863	            schema.hiloUniversityTaskSteps.taskId,
864	            schema.hiloUniversityLessonTasks.id,
865	          ),
866	        )
867	        .where(eq(schema.hiloUniversityTaskSteps.id, stepId))
868	        .limit(1);
869	
870	      if (!stepWithLesson) {
871	        return c.json({ error: 'Step not found' }, 404);
872	      }
873	      const { taskId, lessonId } = stepWithLesson;
874	
875	      const result = await db.transaction(async (tx) => {
876	        await tx
877	          .insert(schema.hiloUniversityLessonStepCompletions)
878	          .values({
879	            userId,
880	            flightSchoolId,
881	            stepId,
882	          })
883	          .onConflictDoNothing();
884	
885	        // Recompute task completion: all steps for the task complete?
886	        const taskStepIdRows = await tx
887	          .select({ id: schema.hiloUniversityTaskSteps.id })
888	          .from(schema.hiloUniversityTaskSteps)
889	          .where(eq(schema.hiloUniversityTaskSteps.taskId, taskId));
890	        const taskStepIds = taskStepIdRows.map((r) => r.id);
891	
892	        let taskCompletedAll = false;
893	        if (taskStepIds.length > 0) {
894	          const completedForTask = await tx
895	            .select({
896	              stepId: schema.hiloUniversityLessonStepCompletions.stepId,
897	            })
898	            .from(schema.hiloUniversityLessonStepCompletions)
899	            .where(
900	              and(
901	                eq(schema.hiloUniversityLessonStepCompletions.userId, userId),
902	                eq(
903	                  schema.hiloUniversityLessonStepCompletions.flightSchoolId,
904	                  flightSchoolId,
905	                ),
906	                inArray(
907	                  schema.hiloUniversityLessonStepCompletions.stepId,
908	                  taskStepIds,
909	                ),
910	              ),
911	            );
912	          taskCompletedAll = completedForTask.length === taskStepIds.length;
913	          if (taskCompletedAll) {
914	            await tx
915	              .insert(schema.hiloUniversityLessonTaskCompletions)
916	              .values({
917	                userId,
918	                flightSchoolId,
919	                taskId,
920	              })
921	              .onConflictDoNothing();
922	          }
923	        }
924	
925	        // Recompute lesson percent across ALL steps in the lesson.
926	        const lessonTaskIdRows = await tx
927	          .select({ id: schema.hiloUniversityLessonTasks.id })
928	          .from(schema.hiloUniversityLessonTasks)
929	          .where(eq(schema.hiloUniversityLessonTasks.lessonId, lessonId));
930	        const lessonTaskIds = lessonTaskIdRows.map((r) => r.id);
931	
932	        let totalSteps = 0;
933	        let completedSteps = 0;
934	        if (lessonTaskIds.length > 0) {
935	          const allStepRows = await tx
936	            .select({ id: schema.hiloUniversityTaskSteps.id })
937	            .from(schema.hiloUniversityTaskSteps)
938	            .where(
939	              inArray(schema.hiloUniversityTaskSteps.taskId, lessonTaskIds),
940	            );
941	          totalSteps = allStepRows.length;
942	          if (totalSteps > 0) {
943	            const completed = await tx
944	              .select({
945	                stepId: schema.hiloUniversityLessonStepCompletions.stepId,
946	              })
947	              .from(schema.hiloUniversityLessonStepCompletions)
948	              .where(
949	                and(
950	                  eq(schema.hiloUniversityLessonStepCompletions.userId, userId),
951	                  eq(
952	                    schema.hiloUniversityLessonStepCompletions.flightSchoolId,
953	                    flightSchoolId,
954	                  ),
955	                  inArray(
956	                    schema.hiloUniversityLessonStepCompletions.stepId,
957	                    allStepRows.map((r) => r.id),
958	                  ),
959	                ),
960	              );
961	            completedSteps = completed.length;
962	          }
963	        }
964	
965	        const percent =
966	          totalSteps === 0
967	            ? 0
968	            : Math.round((completedSteps / totalSteps) * 100);
969	        const lessonStatus: 'in_progress' | 'completed' =
970	          percent >= 100 ? 'completed' : 'in_progress';
971	
972	        await tx
973	          .insert(schema.hiloUniversityLessonProgress)
974	          .values({
975	            userId,
976	            flightSchoolId,
977	            lessonId,
978	            lastStepId: stepId,
