984	              schema.hiloUniversityLessonProgress.userId,
985	              schema.hiloUniversityLessonProgress.lessonId,
986	            ],
987	            set: {
988	              lastStepId: stepId,
989	              status: lessonStatus,
990	              percentComplete: percent,
991	            },
992	          });
993	
994	        return {
995	          percentComplete: percent,
996	          status: lessonStatus,
997	          taskCompleted: taskCompletedAll,
998	        };
999	      });
1000	
1001	      return c.json({ ok: true, ...result });
