809	/**
810	 * BFS over the proposed prerequisite graph starting at the prereqs of
811	 * `lessonId`. Returns the cycle path (lessonId reachable from itself) or
812	 * null if the proposed graph is acyclic.
813	 */
814	async function detectPrereqCycle(
815	  lessonId: string,
816	  proposedPrereqIds: string[],
817	): Promise<string[] | null> {
818	  if (proposedPrereqIds.includes(lessonId)) {
819	    return [lessonId, lessonId];
820	  }
821	
822	  const allEdges = await db
823	    .select({
824	      lessonId: schema.hiloUniversityLessonPrerequisites.lessonId,
825	      prerequisiteLessonId:
826	        schema.hiloUniversityLessonPrerequisites.prerequisiteLessonId,
827	    })
828	    .from(schema.hiloUniversityLessonPrerequisites);
829	
830	  const adjacency = new Map<string, string[]>();
831	  for (const edge of allEdges) {
832	    if (edge.lessonId === lessonId) continue;
833	    const list = adjacency.get(edge.lessonId) ?? [];
834	    list.push(edge.prerequisiteLessonId);
835	    adjacency.set(edge.lessonId, list);
836	  }
837	  adjacency.set(lessonId, proposedPrereqIds);
838	
839	  const parent = new Map<string, string>();
840	  const queue: string[] = [...proposedPrereqIds];
841	  const visited = new Set<string>();
842	  for (const id of proposedPrereqIds) parent.set(id, lessonId);
843	
844	  while (queue.length > 0) {
845	    const current = queue.shift() as string;
846	    if (current === lessonId) {
847	      const path: string[] = [lessonId];
848	      let cursor: string | undefined = current;
849	      while (cursor !== undefined && cursor !== lessonId) {
850	        path.unshift(cursor);
851	        cursor = parent.get(cursor);
852	      }
853	      path.unshift(lessonId);
854	      return path;
855	    }
856	    if (visited.has(current)) continue;
857	    visited.add(current);
858	    const next = adjacency.get(current) ?? [];
859	    for (const n of next) {
860	      if (!parent.has(n)) parent.set(n, current);
861	      queue.push(n);
862	    }
863	  }
864	
865	  return null;
866	}
