951	/**
952	 * Verifies a lesson meets the publish minimum bar. Per technical-spec §2.1:
953	 *   (goals.length >= 1) OR (tasks.length >= 1 AND any step) OR (video_url IS NOT NULL)
954	 *   AND roles.length >= 1
955	 *   AND title IS NOT NULL
956	 *   AND every step.target_route resolves against the route registry
957	 *
958	 * Returns { ok: true } when all gates pass, or { ok: false, missing } with the
959	 * canonical field names from `PublishMinimumBarFields`.
960	 */
961	async function checkPublishMinimumBar(
962	  lessonId: string,
963	): Promise<PublishCheckResult> {
964	  const [lesson] = await db
965	    .select({
966	      id: schema.hiloUniversityLessons.id,
967	      title: schema.hiloUniversityLessons.title,
968	      videoUrl: schema.hiloUniversityLessons.videoUrl,
969	      roles: schema.hiloUniversityLessons.roles,
970	    })
971	    .from(schema.hiloUniversityLessons)
972	    .where(eq(schema.hiloUniversityLessons.id, lessonId))
973	    .limit(1);
974	  if (!lesson) return { ok: false, missing: PublishMinimumBarFields.slice() };
975	
976	  const missing: string[] = [];
977	  if (!lesson.title || lesson.title.trim() === '') missing.push('title');
978	  const roles = (lesson.roles as string[] | null) ?? [];
979	  if (roles.length === 0) missing.push('roles');
980	
981	  const goalCount = await db.$count(
982	    schema.hiloUniversityLessonGoals,
983	    eq(schema.hiloUniversityLessonGoals.lessonId, lessonId),
984	  );
985	  const tasks = await db
986	    .select({ id: schema.hiloUniversityLessonTasks.id })
987	    .from(schema.hiloUniversityLessonTasks)
988	    .where(eq(schema.hiloUniversityLessonTasks.lessonId, lessonId));
989	
990	  let stepCount = 0;
991	  if (tasks.length > 0) {
992	    stepCount = await db.$count(
993	      schema.hiloUniversityTaskSteps,
994	      inArray(
995	        schema.hiloUniversityTaskSteps.taskId,
996	        tasks.map((t) => t.id),
997	      ),
998	    );
999	  }
1000	
1001	  const hasGoals = goalCount > 0;
1002	  const hasTaskWithStep = tasks.length > 0 && stepCount > 0;
1003	  const hasVideo = !!lesson.videoUrl && lesson.videoUrl.trim() !== '';
1004	  if (!(hasGoals || hasTaskWithStep || hasVideo)) {
1005	    missing.push('content');
1006	  }
1007	
1008	  if (tasks.length > 0) {
1009	    const steps = await db
1010	      .select({ targetRoute: schema.hiloUniversityTaskSteps.targetRoute })
1011	      .from(schema.hiloUniversityTaskSteps)
