1	/**
2	 * Hilo University v1 — AI generation routes (super-admin only).
3	 *
4	 * Combines the two Wave 3 AI flows onto a single Hono router:
5	 *   - POST /hilo-university/admin/lessons/generate-from-source   (w3-a2)
6	 *       Body: `AiGenerateFromSourcePayloadSchema`. Enqueues Inngest
7	 *       `university/lesson.generate-from-source`. Returns `{ jobId }` (202).
8	 *   - POST /hilo-university/admin/lessons/:lessonId/generate-tasks  (w3-a3)
9	 *       Body: `AiTasksFromDescriptionPayloadSchema`. Enqueues Inngest
10	 *       `university/tasks.generate-from-description`. Returns `{ jobId }` (202).
11	 *   - GET  /hilo-university/admin/lessons/ai-result/:jobId
12	 *       Polling endpoint shared by both flows. Reads the single Redis-backed
13	 *       result store.
14	 *
15	 * Auth: `requireSuperAdmin()` on every handler. No tenant scoping — these
16	 * routes deal with global content (Wave 1 schema decision).
17	 *
18	 * @see docs/plans/hilo-university-v1/technical-spec.md §6.1, §6.2
19	 */
20	
21	import {
22	  ROUTES,
23	  filterRoutesByAudience,
24	} from '@/components/features/mvp-v2/routes-registry';
25	import { getAnthropicKey } from '@/lib/anthropic/api-key';
26	import { buildTasksInterviewSystemPrompt } from '@/lib/anthropic/prompts/university/tasks-from-description';
27	import {
28	  type GeneratedResult,
29	  validateGeneratedRoutes,
30	} from '@/lib/anthropic/validators/route-validator';
31	import { db } from '@/lib/db';
32	import { inngest } from '@/lib/inngest/client';
33	import { ANTHROPIC_MODEL } from '@/lib/orchestrator/config';
34	import * as schema from '@/lib/schema';
35	import {
36	  AiGenerateFromSourcePayloadSchema,
37	  AiTasksFromDescriptionPayloadSchema,
38	} from '@/lib/schema/zod/hilo-university-v2';
39	import { getAiJobRecord } from '@/server/lib/hilo-university-ai-result-store';
40	import { requireSuperAdmin } from '@/server/middleware/auth';
41	import type { AuthUser } from '@/server/middleware/auth';
42	import { eq } from 'drizzle-orm';
43	import { Hono } from 'hono';
44	import { z } from 'zod';
45	
46	export const hiloUniversityAiRoutes = new Hono<{
47	  Variables: { authUser?: AuthUser };
48	}>();
49	
50	function randomJobId(): string {
51	  // crypto.randomUUID is on Web Crypto in Node 19+ (the runtime targeted by
52	  // this app) and Vercel Functions. jobIds are opaque correlation handles.
53	  return crypto.randomUUID();
54	}
55	
56	// ─── POST /admin/lessons/generate-from-source (w3-a2) ────────────────────
57	
58	hiloUniversityAiRoutes.post(
59	  '/hilo-university/admin/lessons/generate-from-source',
60	  requireSuperAdmin(),
61	  async (c) => {
62	    const body = await c.req.json().catch(() => ({}));
63	    const parsed = AiGenerateFromSourcePayloadSchema.safeParse(body);
64	    if (!parsed.success) {
65	      return c.json(
66	        { code: 'INVALID_BODY', issues: parsed.error.flatten() },
67	        422,
68	      );
69	    }
70	
71	    const jobId = randomJobId();
72	    const actor = (c.get('authUser') as AuthUser | undefined)?.id;
73	
74	    try {
75	      await inngest.send({
76	        name: 'university/lesson.generate-from-source',
77	        data: {
78	          jobId,
79	          mode: parsed.data.mode,
80	          categoryId: parsed.data.categoryId,
81	          fileUrl:
82	            parsed.data.mode === 'pdf' || parsed.data.mode === 'docx'
83	              ? parsed.data.fileUrl
84	              : undefined,
85	          text: parsed.data.mode === 'text' ? parsed.data.text : undefined,
86	          requestedByUserId: actor,
87	        },
88	      });
89	    } catch (err) {
90	      return c.json(
91	        {
92	          code: 'ENQUEUE_FAILED',
93	          error: err instanceof Error ? err.message : String(err),
94	        },
95	        500,
96	      );
97	    }
98	
99	    return c.json({ jobId }, 202);
100	  },
101	);
102	
103	// ─── POST /admin/lessons/:lessonId/generate-tasks (w3-a3) ────────────────
104	
105	hiloUniversityAiRoutes.post(
106	  '/hilo-university/admin/lessons/:lessonId/generate-tasks',
107	  requireSuperAdmin(),
108	  async (c) => {
109	    const { lessonId } = c.req.param();
110	    const authUser = c.get('authUser') as AuthUser | undefined;
111	
112	    let body: unknown;
113	    try {
114	      body = await c.req.json();
115	    } catch {
116	      return c.json({ error: 'Invalid JSON body' }, 400);
117	    }
118	
119	    const parsed = AiTasksFromDescriptionPayloadSchema.safeParse(body);
120	    if (!parsed.success) {
121	      return c.json(
122	        { error: 'Invalid payload', issues: parsed.error.issues },
123	        422,
124	      );
125	    }
126	
127	    const [lesson] = await db
128	      .select({
129	        id: schema.hiloUniversityLessons.id,
130	        title: schema.hiloUniversityLessons.title,
131	      })
132	      .from(schema.hiloUniversityLessons)
133	      .where(eq(schema.hiloUniversityLessons.id, lessonId))
134	      .limit(1);
135	
136	    if (!lesson) return c.json({ error: 'Lesson not found' }, 404);
137	
138	    const jobId = randomJobId();
139	    await inngest.send({
140	      name: 'university/tasks.generate-from-description',
141	      data: {
142	        jobId,
143	        lessonId,
144	        roles: parsed.data.roles,
145	        requestedByUserId: authUser?.id ?? 'unknown',
146	      },
147	    });
148	
149	    return c.json({ jobId, status: 'pending' as const }, 202);
150	  },
151	);
152	
153	// ─── POST /admin/lessons/:lessonId/generate-tasks/chat (interview) ───────
154	// Interactive, interview-style task generation. The author edits the prompt
155	// (`instructions`) and chats turn-by-turn; the model asks clarifying questions
156	// and, when ready, returns a `draft` of tasks the author reviews + accepts in
157	// the drawer. Synchronous (single Anthropic call per turn) — unlike the
158	// one-shot Inngest flow above — because a conversation needs an immediate reply.
159	
160	// The five Hilo University audience role tags. Mirrors `RoleAudience` in the
161	// route registry — validated as a closed enum so untrusted client input can
162	// never reach `filterRoutesByAudience` as an arbitrary string.
163	const HU_ROLE_VALUES = [
164	  'student',
165	  'instructor',
166	  'admin',
167	  'mechanic',
168	  'global',
169	] as const;
170	
171	const TasksChatSchema = z.object({
172	  messages: z
173	    .array(
174	      z.object({
175	        role: z.enum(['user', 'assistant']),
176	        content: z.string().min(1).max(8000),
177	      }),
178	    )
179	    .min(1)
180	    .max(40),
181	  roles: z.array(z.enum(HU_ROLE_VALUES)).max(8).default([]),
182	  instructions: z.string().max(4000).optional(),
183	});
184	
185	// Vercel Function maxDuration for this route's deployment is 60s; keep the
186	// upstream call comfortably under it so the function returns a clean 504
187	// rather than being killed by the platform.
188	const TASKS_CHAT_TIMEOUT_MS = 50_000;
189	
190	/**
191	 * Extract a fenced ```json { tasks: [...] } block from the model reply.
192	 * Returns the permissive `GeneratedResult` shape (same type the route
193	 * validator consumes) after a runtime check that `tasks` is an array — the
194	 * single cast is justified by that guard, not an unchecked assertion.
195	 */
196	function extractTasksDraft(text: string): GeneratedResult | null {
197	  const fence =
198	    text.match(/```json\s*([\s\S]*?)```/i) ?? text.match(/```\s*([\s\S]*?)```/);
199	  if (!fence) return null;
200	  try {
201	    const parsed: unknown = JSON.parse(fence[1].trim());
202	    if (
203	      parsed &&
204	      typeof parsed === 'object' &&
205	      Array.isArray((parsed as { tasks?: unknown }).tasks)
206	    ) {
207	      return parsed as GeneratedResult;
208	    }
209	  } catch {
210	    /* not valid JSON — treat as a conversational turn */
211	  }
212	  return null;
213	}
214	
215	/** Remove the fenced JSON block so the chat shows only the human-readable lead-in. */
216	function stripJsonBlock(text: string): string {
217	  return text
218	    .replace(/```json[\s\S]*?```/i, '')
219	    .replace(/```[\s\S]*?```/, '')
220	    .trim();
221	}
222	
223	hiloUniversityAiRoutes.post(
224	  '/hilo-university/admin/lessons/:lessonId/generate-tasks/chat',
225	  requireSuperAdmin(),
226	  async (c) => {
227	    const { lessonId } = c.req.param();
228	    const body = await c.req.json().catch(() => ({}));
229	    const parsed = TasksChatSchema.safeParse(body);
230	    if (!parsed.success) {
231	      return c.json(
232	        { code: 'INVALID_BODY', issues: parsed.error.flatten() },
233	        422,
234	      );
235	    }
236	
237	    // Platform-global content: Hilo University lessons are NOT tenant-scoped
238	    // (Wave 1 schema decision — see file header + technical-spec §6). There is
239	    // no `orgId` column to enforce. Access is gated entirely by
240	    // `requireSuperAdmin()` above; super-admins legitimately author content
241	    // shared across every tenant. A `lessonId`-only lookup is correct here and
242	    // mirrors the sibling `generate-tasks` and `generate-from-source` handlers.
243	    const [lesson] = await db
244	      .select({
245	        id: schema.hiloUniversityLessons.id,
246	        title: schema.hiloUniversityLessons.title,
247	        description: schema.hiloUniversityLessons.description,
248	      })
249	      .from(schema.hiloUniversityLessons)
250	      .where(eq(schema.hiloUniversityLessons.id, lessonId))
251	      .limit(1);
252	    if (!lesson) return c.json({ error: 'Lesson not found' }, 404);
253	
254	    const apiKey = getAnthropicKey('university-tasks-from-description');
255	    if (!apiKey) return c.json({ error: 'AI is not configured.' }, 503);
256	
257	    // `parsed.data.roles` is already narrowed to the role enum by Zod, so it
258	    // is structurally a `RoleAudience[]` — no cast needed.
259	    const audienceRoutes = filterRoutesByAudience(parsed.data.roles);
260	    const system = buildTasksInterviewSystemPrompt(
261	      {
262	        lesson: { title: lesson.title, description: lesson.description },
263	        roles: parsed.data.roles,
264	        routes: audienceRoutes,
265	      },
266	      parsed.data.instructions,
267	    );
268	
269	    const controller = new AbortController();
270	    const timeout = setTimeout(() => controller.abort(), TASKS_CHAT_TIMEOUT_MS);
271	    let replyText: string;
272	    try {
273	      const res = await fetch('https://api.anthropic.com/v1/messages', {
274	        method: 'POST',
275	        headers: {
276	          'Content-Type': 'application/json',
277	          'x-api-key': apiKey,
278	          'anthropic-version': '2023-06-01',
279	        },
280	        signal: controller.signal,
281	        body: JSON.stringify({
282	          model: ANTHROPIC_MODEL,
283	          max_tokens: 4096,
284	          system,
285	          messages: parsed.data.messages,
286	        }),
287	      });
288	      if (!res.ok) {
289	        // Log upstream diagnostics server-side only — never return raw provider
290	        // error text to the client (it can leak request/account details).
291	        const errText = await res.text();
292	        console.error(
293	          `[hu-generate-tasks-chat] Anthropic ${res.status}: ${errText.slice(0, 500)}`,
294	        );
295	        return c.json({ error: `AI request failed (${res.status})` }, 502);
296	      }
297	      const data = await res.json();
298	      const block = (data.content ?? []).find(
299	        (b: { type: string; text?: string }) => b.type === 'text',
300	      );
301	      replyText = block?.text ?? '';
302	    } catch (err) {
303	      const aborted = err instanceof Error && err.name === 'AbortError';
304	      return c.json(
305	        {
306	          error: aborted
307	            ? 'AI request timed out. Try again.'
308	            : 'AI request failed.',
309	        },
310	        aborted ? 504 : 500,
311	      );
312	    } finally {
313	      clearTimeout(timeout);
314	    }
315	
316	    const draft = extractTasksDraft(replyText);
317	    if (draft) {
318	      const outcome = validateGeneratedRoutes(draft, ROUTES);
319	      const lead = stripJsonBlock(replyText);
320	      return c.json({
321	        reply:
322	          lead ||
323	          'Here is a draft set of tasks. Review and accept the ones you want, or tell me what to change.',
324	        draft: { tasks: draft.tasks, invalidRoutes: outcome.invalidRoutes },
325	      });
326	    }
327	
328	    return c.json({ reply: replyText });
329	  },
330	);
331	
332	// ─── GET /admin/lessons/ai-result/:jobId (shared poll) ───────────────────
333	
334	hiloUniversityAiRoutes.get(
335	  '/hilo-university/admin/lessons/ai-result/:jobId',
336	  requireSuperAdmin(),
337	  async (c) => {
338	    const { jobId } = c.req.param();
339	    const record = await getAiJobRecord(jobId);
340	    if (record) return c.json(record);
341	
342	    // Not in the store yet — treat as still pending rather than 404 so the
343	    // drawer keeps polling immediately after enqueue. Shape matches the
344	    // from-source contract its test asserts: { status: 'pending' }.
345	    return c.json({ status: 'pending' as const });
346	  },
347	);
348	
349	// Pure helpers exported for unit testing only — not part of the public router.
350	export const _internalForTest = {
351	  TasksChatSchema,
352	  extractTasksDraft,
353	  stripJsonBlock,
354	  HU_ROLE_VALUES,
355	};
