1	/**
2	 * Hilo University — Lesson Assignment Routes
3	 *
4	 * Org-scoped CRUD for `hilo_university_lesson_assignments`. v1 has zero
5	 * out-of-band side effects: assignments surface in-app only via
6	 * `/assignments/me`. See validation item 11.25 — handlers must not import
7	 * or call any out-of-band transport (audit greps the file for transport
8	 * keywords).
9	 */
10	
11	import { db } from '@/lib/db';
12	import { formatErrorForUser } from '@/lib/errors/format-error-for-user';
13	import * as schema from '@/lib/schema';
14	import {
15	  type AuthUser,
16	  requireAdmin,
17	  requireAuth,
18	} from '@/server/middleware/auth';
19	import { and, eq, or } from 'drizzle-orm';
20	import type { Context } from 'hono';
21	import { Hono } from 'hono';
22	
23	export const hiloUniversityAssignmentsRoutes = new Hono<{
24	  Variables: { authUser?: AuthUser };
25	}>();
26	
27	const UUID_RE =
28	  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
29	
30	const ASSIGNABLE_ROLES = ['student', 'instructor', 'admin', 'mechanic'];
31	
32	/**
33	 * Resolve the caller's Hilo `users.id` (uuid), flight school, and team role.
34	 *
35	 * Better Auth `user.id` is a CUID2 text value that does NOT match the
36	 * application `users.id` uuid column — comparing them directly throws Postgres
37	 * 22P02 (invalid input syntax for type uuid). We always look the Hilo id up by
38	 * email; super_admins may not have a school-scoped `users` row, in which case
39	 * `userId` is null and the caller decides whether the operation is permitted.
40	 */
41	async function resolveCallerIdentity(
42	  authUser: AuthUser,
43	  c: Context,
44	): Promise<{
45	  schoolId: string | null;
46	  teamRole: string | null;
47	  userId: string | null;
48	}> {
49	  const [row] = await db
50	    .select({
51	      id: schema.users.id,
52	      schoolId: schema.users.flightSchoolId,
53	      teamRole: schema.users.role,
54	    })
55	    .from(schema.users)
56	    .where(eq(schema.users.email, authUser.email))
57	    .limit(1);
58	
59	  if (authUser.role === 'super_admin') {
60	    const managed = c.get('managedSchoolId') as string | undefined;
61	    if (managed) {
62	      return { schoolId: managed, teamRole: null, userId: row?.id ?? null };
63	    }
64	  }
65	
66	  return {
67	    schoolId: row?.schoolId ?? null,
68	    teamRole: row?.teamRole ?? null,
69	    userId: row?.id ?? null,
70	  };
71	}
72	
73	function structuredError(c: Context, err: unknown) {
74	  const structured = formatErrorForUser(err, {
75	    feature: 'HILU',
76	    actor: (c.get('authUser') as AuthUser | undefined)?.id,
77	  });
78	  return c.json(
79	    {
80	      error: structured.message,
81	      reference_id: structured.reference_id,
82	      retry_safe: structured.retry_safe,
83	    },
84	    500,
85	  );
86	}
87	
88	// ─── POST /hilo-university/assignments ────────────────────────────────────────
89	
90	hiloUniversityAssignmentsRoutes.post(
91	  '/hilo-university/assignments',
92	  requireAdmin(),
93	  async (c) => {
94	    const authUser = c.get('authUser') as AuthUser;
95	    try {
96	      const body = (await c.req.json().catch(() => null)) as {
97	        lessonId?: unknown;
98	        userId?: unknown;
99	        role?: unknown;
100	      } | null;
101	
102	      if (!body || typeof body !== 'object') {
103	        return c.json({ error: 'Invalid JSON body' }, 422);
104	      }
105	
106	      const lessonId = typeof body.lessonId === 'string' ? body.lessonId : null;
107	      const targetUserId = typeof body.userId === 'string' ? body.userId : null;
108	      const role = typeof body.role === 'string' ? body.role : null;
109	
110	      if (!lessonId || !UUID_RE.test(lessonId)) {
111	        return c.json({ error: 'lessonId must be a uuid' }, 422);
112	      }
113	
114	      const hasUser = targetUserId !== null;
115	      const hasRole = role !== null;
116	      if (hasUser === hasRole) {
117	        return c.json(
118	          { error: 'Exactly one of userId or role must be provided' },
119	          422,
120	        );
121	      }
122	
123	      if (hasUser && !UUID_RE.test(targetUserId as string)) {
124	        return c.json({ error: 'userId must be a uuid' }, 422);
125	      }
126	
127	      if (hasRole && !ASSIGNABLE_ROLES.includes(role as string)) {
128	        return c.json(
129	          { error: `role must be one of [${ASSIGNABLE_ROLES.join(', ')}]` },
130	          422,
131	        );
132	      }
133	
134	      const { schoolId: callerSchoolId, userId: callerUserId } =
135	        await resolveCallerIdentity(authUser, c);
136	      if (!callerSchoolId) {
137	        return c.json({ error: 'Could not resolve organization' }, 403);
138	      }
139	      // assigned_by_user_id is a uuid FK to users.id. Better Auth's authUser.id
140	      // is a CUID2 text value that does NOT match users.id (would throw 22P02
141	      // and was the source of 100+ Sentry 5xx/6h). We resolve the Hilo users.id
142	      // by email in resolveCallerIdentity and require it for the INSERT.
143	      if (!callerUserId) {
144	        return c.json(
145	          {
146	            error:
147	              'Caller has no Hilo user account; assignments require a school-scoped identity.',
148	          },
149	          403,
150	        );
151	      }
152	
153	      const [lesson] = await db
154	        .select({ id: schema.hiloUniversityLessons.id })
155	        .from(schema.hiloUniversityLessons)
156	        .where(eq(schema.hiloUniversityLessons.id, lessonId))
157	        .limit(1);
158	      if (!lesson) {
159	        return c.json({ error: 'Lesson not found' }, 404);
160	      }
161	
162	      if (hasUser) {
163	        const [targetUser] = await db
164	          .select({
165	            id: schema.users.id,
166	            schoolId: schema.users.flightSchoolId,
167	          })
168	          .from(schema.users)
169	          .where(eq(schema.users.id, targetUserId as string))
170	          .limit(1);
171	
172	        if (!targetUser) {
173	          return c.json({ error: 'Target user not found' }, 404);
174	        }
175	        if (
176	          authUser.role !== 'super_admin' &&
177	          targetUser.schoolId !== callerSchoolId
178	        ) {
179	          return c.json({ error: 'Target user not in your organization' }, 403);
180	        }
181	      }
182	
183	      const [inserted] = await db
184	        .insert(schema.hiloUniversityLessonAssignments)
185	        .values({
186	          lessonId,
187	          flightSchoolId: callerSchoolId,
188	          assignedToUserId: hasUser ? (targetUserId as string) : null,
189	          assignedToRole: hasRole ? (role as string) : null,
190	          assignedByUserId: callerUserId,
191	        })
192	        .returning();
193	
194	      return c.json({ assignment: inserted }, 201);
195	    } catch (err) {
196	      return structuredError(c, err);
197	    }
198	  },
199	);
200	
201	// ─── DELETE /hilo-university/assignments/:id ──────────────────────────────────
202	
203	hiloUniversityAssignmentsRoutes.delete(
204	  '/hilo-university/assignments/:id',
205	  requireAdmin(),
206	  async (c) => {
207	    const authUser = c.get('authUser') as AuthUser;
208	    const { id } = c.req.param();
209	    try {
210	      if (!UUID_RE.test(id)) {
211	        return c.json({ error: 'Invalid assignment id' }, 422);
212	      }
213	
214	      const { schoolId: callerSchoolId } = await resolveCallerIdentity(
215	        authUser,
216	        c,
217	      );
218	      if (!callerSchoolId) {
219	        return c.json({ error: 'Could not resolve organization' }, 403);
220	      }
221	
222	      const whereClause =
223	        authUser.role === 'super_admin'
224	          ? eq(schema.hiloUniversityLessonAssignments.id, id)
225	          : and(
226	              eq(schema.hiloUniversityLessonAssignments.id, id),
227	              eq(
228	                schema.hiloUniversityLessonAssignments.flightSchoolId,
229	                callerSchoolId,
230	              ),
231	            );
232	
233	      const deleted = await db
234	        .delete(schema.hiloUniversityLessonAssignments)
235	        .where(whereClause)
236	        .returning({ id: schema.hiloUniversityLessonAssignments.id });
237	
238	      if (deleted.length === 0) {
239	        return c.json({ error: 'Assignment not found' }, 404);
240	      }
241	
242	      return c.json({ ok: true });
243	    } catch (err) {
244	      return structuredError(c, err);
245	    }
246	  },
247	);
248	
249	// ─── GET /hilo-university/assignments/lesson/:lessonId ────────────────────────
250	
251	hiloUniversityAssignmentsRoutes.get(
252	  '/hilo-university/assignments/lesson/:lessonId',
253	  requireAdmin(),
254	  async (c) => {
255	    const authUser = c.get('authUser') as AuthUser;
256	    const { lessonId } = c.req.param();
257	    try {
258	      if (!UUID_RE.test(lessonId)) {
