1	/**
2	 * Hilo University — Admin Analytics Routes (w2-a4-analytics)
3	 *
4	 * Three endpoints feeding the admin analytics surface:
5	 *   GET /hilo-university/admin-analytics/lessons/:lessonId/completion
6	 *   GET /hilo-university/admin-analytics/users
7	 *   GET /hilo-university/admin-analytics/coverage-by-role
8	 *
9	 * Org-scoping invariant: every progress / completion / assignment / user
10	 * query in this file MUST include `flightSchoolId` in the predicate chain.
11	 * Super admins may target other orgs via `?flightSchoolId=<uuid>`; org
12	 * admins who supply that param are silently ignored (warning logged) and
13	 * served their own org's data, per validation criterion 11.16.
14	 *
15	 * The coverage-by-role endpoint is a shell until the
16	 * `hilo_university_coverage_cache` table lands. See ESCALATION block below.
17	 */
18	
19	import { db } from '@/lib/db';
20	import { formatErrorForUser } from '@/lib/errors/format-error-for-user';
21	import { inngest } from '@/lib/inngest/client';
22	import {
23	  aggregateLessonsByRole,
24	  getCoverageGapCacheSnapshot,
25	  isCoverageGapCacheFresh,
26	} from '@/lib/inngest/functions/university-coverage-gap';
27	import * as schema from '@/lib/schema';
28	import { isUuid } from '@/server/helpers';
29	import { requireAdmin, requireSuperAdmin } from '@/server/middleware/auth';
30	import type { AuthUser } from '@/server/middleware/auth';
31	import { and, eq, inArray } from 'drizzle-orm';
32	import { Hono } from 'hono';
33	
34	export const hiloUniversityAnalyticsRoutes = new Hono<{
35	  Variables: { authUser?: AuthUser };
36	}>();
37	
38	// ─── COVERAGE CACHE NOTE ─────────────────────────────────────────────────────
39	// Per Shane's 2026-05-30 decision, the coverage-gap report does NOT persist
40	// to a DB table — it's a derived artifact and recomputing on cold start is
41	// acceptable. The cache lives as module-level state inside
42	// `src/lib/inngest/functions/university-coverage-gap.ts` and the Inngest
43	// job populates it. This endpoint reads via getCoverageGapCacheSnapshot();
44	// when the snapshot is stale or absent it enqueues a refresh and returns
45	// 202 { cacheStatus: 'pending' }. When the snapshot is fresh it returns
46	// cacheStatus: 'fresh' with the AI-derived suggestedTopics, while the
47	// per-role lessonCount is always computed synchronously from the DB so
48	// the numbers stay accurate even if the AI portion is mid-refresh.
49	//
50	// Limitation: because the cache is in-memory, the route handler invocation
51	// and the Inngest function invocation may see different snapshots until
52	// both have warmed. This is the documented v1 behavior — see the prompt
53	// for w3-a4.
54	// ─────────────────────────────────────────────────────────────────────────────
55	
56	/**
57	 * Resolves the org context for an analytics call.
58	 *
59	 * Rules:
60	 *   - super_admin may target another org via the `flightSchoolId` query param
61	 *     (validated as UUID).
62	 *   - admin who passes `flightSchoolId` is silently ignored (warning logged)
63	 *     and gets their own org's data — see validation criterion 11.16.
64	 *   - Both roles get a 400 if their session user row is missing or has no
65	 *     flight school (mirrors the existing pattern at
66	 *     routes-hilo-university.ts:353-358).
67	 */
68	async function resolveAnalyticsOrgId(
69	  authUser: AuthUser,
70	  requestedFlightSchoolId: string | undefined,
71	): Promise<
72	  | { ok: true; flightSchoolId: string }
73	  | { ok: false; status: 400 | 403; error: string }
74	> {
75	  // authUser.id is a Better Auth text/CUID2 value and does NOT match the
76	  // application users.id uuid column — comparing them directly throws 22P02.
77	  // The two tables are linked by email, not by id.
78	  const [callerRow] = await db
79	    .select({ flightSchoolId: schema.users.flightSchoolId })
80	    .from(schema.users)
81	    .where(eq(schema.users.email, authUser.email))
82	    .limit(1);
83	
84	  const callerSchoolId = callerRow?.flightSchoolId;
85	
86	  if (authUser.role === 'super_admin') {
87	    if (requestedFlightSchoolId) {
88	      if (!isUuid(requestedFlightSchoolId)) {
89	        return { ok: false, status: 400, error: 'Invalid flightSchoolId' };
90	      }
91	      return { ok: true, flightSchoolId: requestedFlightSchoolId };
92	    }
93	    if (!callerSchoolId) {
94	      return {
95	        ok: false,
96	        status: 400,
97	        error:
98	          'Super admin must pass ?flightSchoolId=<uuid> when not associated with a school',
99	      };
100	    }
101	    return { ok: true, flightSchoolId: callerSchoolId };
102	  }
103	
104	  if (!callerSchoolId) {
105	    return { ok: false, status: 400, error: 'User missing flight school' };
106	  }
107	
108	  if (requestedFlightSchoolId && requestedFlightSchoolId !== callerSchoolId) {
109	    console.warn(
110	      '[HILU/analytics] org admin requested cross-org flightSchoolId; ignoring param',
111	      {
112	        actor: authUser.id,
113	        callerSchoolId,
114	        requestedFlightSchoolId,
115	      },
116	    );
117	  }
118	
119	  return { ok: true, flightSchoolId: callerSchoolId };
120	}
121	
122	/** Result shape for the per-lesson completion stats endpoint. */
123	interface LessonCompletionStats {
124	  lessonId: string;
125	  totalUsersInOrg: number;
126	  completed: number;
127	  inProgress: number;
128	  notStarted: number;
129	  percentComplete: number;
130	  /**
131	   * True when any task on the lesson has `is_required_for_role[role] = true`
132	   * for at least one role. Cosmetic field — no middleware uses it.
133	   */
134	  isRequiredForAnyRole: boolean;
135	}
136	
137	/**
138	 * GET /hilo-university/admin-analytics/lessons/:lessonId/completion
139	 *
140	 * Per-lesson completion stats for the caller's org. Super admin may pass
141	 * `?flightSchoolId=<uuid>` to target another org.
142	 */
143	hiloUniversityAnalyticsRoutes.get(
144	  '/hilo-university/admin-analytics/lessons/:lessonId/completion',
145	  requireAdmin(),
146	  async (c) => {
147	    const authUser = c.get('authUser') as AuthUser;
148	    const { lessonId } = c.req.param();
149	    if (!isUuid(lessonId)) {
150	      return c.json({ error: 'Invalid lessonId' }, 400);
151	    }
152	
153	    try {
154	      const resolved = await resolveAnalyticsOrgId(
155	        authUser,
156	        c.req.query('flightSchoolId'),
157	      );
158	      if (!resolved.ok) {
159	        return c.json({ error: resolved.error }, resolved.status);
160	      }
161	      const { flightSchoolId } = resolved;
162	
163	      // Total users in the org (matches what the org admin can see).
164	      const orgUsers = await db
165	        .select({ id: schema.users.id })
166	        .from(schema.users)
167	        .where(eq(schema.users.flightSchoolId, flightSchoolId));
168	      const totalUsersInOrg = orgUsers.length;
169	
170	      // Progress rows for this lesson in this org.
171	      const progressRows = await db
172	        .select({
173	          userId: schema.hiloUniversityLessonProgress.userId,
174	          status: schema.hiloUniversityLessonProgress.status,
175	          percentComplete: schema.hiloUniversityLessonProgress.percentComplete,
176	        })
177	        .from(schema.hiloUniversityLessonProgress)
178	        .where(
179	          and(
180	            eq(schema.hiloUniversityLessonProgress.lessonId, lessonId),
181	            eq(
182	              schema.hiloUniversityLessonProgress.flightSchoolId,
183	              flightSchoolId,
184	            ),
185	          ),
186	        );
187	
188	      // Bucket counts must sum to totalUsersInOrg. A user with no progress
189	      // row OR a row whose `status = 'not_started'` lands in the notStarted
190	      // bucket — only `in_progress` and `completed` rows count as making
191	      // progress.
192	      let completed = 0;
193	      let inProgress = 0;
194	      const usersMakingProgress = new Set<string>();
195	      for (const row of progressRows) {
196	        if (row.status === 'completed') {
197	          completed += 1;
198	          usersMakingProgress.add(row.userId);
199	        } else if (row.status === 'in_progress') {
200	          inProgress += 1;
201	          usersMakingProgress.add(row.userId);
202	        }
203	      }
204	      const notStarted = Math.max(
205	        0,
206	        totalUsersInOrg - usersMakingProgress.size,
207	      );
208	      const percentComplete =
209	        totalUsersInOrg === 0
210	          ? 0
211	          : Math.round((completed / totalUsersInOrg) * 100);
212	
213	      // `isRequiredForAnyRole` — cosmetic; no behavior change.
214	      const tasks = await db
215	        .select({
216	          isRequiredForRole: schema.hiloUniversityLessonTasks.isRequiredForRole,
217	        })
218	        .from(schema.hiloUniversityLessonTasks)
219	        .where(eq(schema.hiloUniversityLessonTasks.lessonId, lessonId));
220	      const isRequiredForAnyRole = tasks.some((t) => {
221	        const rec = t.isRequiredForRole as Record<string, boolean> | null;
222	        if (!rec) return false;
223	        return Object.values(rec).some((v) => v === true);
224	      });
225	
226	      const result: LessonCompletionStats = {
227	        lessonId,
228	        totalUsersInOrg,
229	        completed,
230	        inProgress,
231	        notStarted,
232	        percentComplete,
233	        isRequiredForAnyRole,
234	      };
235	      return c.json(result);
236	    } catch (err) {
237	      const structured = formatErrorForUser(err, {
238	        feature: 'HILU',
239	        actor: authUser.id,
240	      });
241	      return c.json(
242	        {
243	          error: structured.message,
244	          reference_id: structured.reference_id,
245	          retry_safe: structured.retry_safe,
246	        },
247	        500,
248	      );
249	    }
250	  },
251	);
