253	/** Per-user × per-lesson matrix row. */
254	interface AnalyticsLessonCell {
255	  lessonId: string;
256	  title: string;
257	  status: 'not_started' | 'in_progress' | 'completed';
258	  percentComplete: number;
259	  completedAt: string | null;
260	}
261	
262	interface AnalyticsUserRow {
263	  userId: string;
264	  name: string;
265	  role: string;
266	  lessons: AnalyticsLessonCell[];
267	}
268	
269	/**
270	 * GET /hilo-university/admin-analytics/users
271	 *
272	 * Per-user × per-lesson matrix. Org-scoped. Includes only published lessons
273	 * plus archived lessons where at least one user in the org has progress
274	 * (Q3 default per resolved-decisions).
275	 */
276	hiloUniversityAnalyticsRoutes.get(
277	  '/hilo-university/admin-analytics/users',
278	  requireAdmin(),
279	  async (c) => {
280	    const authUser = c.get('authUser') as AuthUser;
281	    try {
282	      const resolved = await resolveAnalyticsOrgId(
283	        authUser,
284	        c.req.query('flightSchoolId'),
285	      );
286	      if (!resolved.ok) {
287	        return c.json({ error: resolved.error }, resolved.status);
288	      }
289	      const { flightSchoolId } = resolved;
290	
291	      // Org users — keep payload size predictable, scope to active roles.
292	      const usersInOrg = await db
293	        .select({
294	          id: schema.users.id,
295	          name: schema.users.name,
296	          role: schema.users.role,
297	        })
298	        .from(schema.users)
299	        .where(eq(schema.users.flightSchoolId, flightSchoolId));
300	
301	      // All progress for this org keyed by user. One row per (user, lesson).
302	      const orgProgress = await db
303	        .select({
304	          userId: schema.hiloUniversityLessonProgress.userId,
305	          lessonId: schema.hiloUniversityLessonProgress.lessonId,
306	          status: schema.hiloUniversityLessonProgress.status,
307	          percentComplete: schema.hiloUniversityLessonProgress.percentComplete,
308	          completedAt: schema.hiloUniversityLessonProgress.completedAt,
309	        })
310	        .from(schema.hiloUniversityLessonProgress)
311	        .where(
312	          eq(
313	            schema.hiloUniversityLessonProgress.flightSchoolId,
314	            flightSchoolId,
315	          ),
316	        );
317	
318	      // Lessons in scope: published + archived-with-progress (Q3 default).
319	      // Two passes: published always, then archived if a progress row exists.
320	      const publishedLessons = await db
321	        .select({
322	          id: schema.hiloUniversityLessons.id,
323	          title: schema.hiloUniversityLessons.title,
324	        })
325	        .from(schema.hiloUniversityLessons)
326	        .where(eq(schema.hiloUniversityLessons.status, 'published'));
327	
328	      const lessonIdsWithProgress = Array.from(
329	        new Set(orgProgress.map((p) => p.lessonId)),
330	      );
331	      const archivedLessons =
332	        lessonIdsWithProgress.length > 0
333	          ? await db
334	              .select({
335	                id: schema.hiloUniversityLessons.id,
336	                title: schema.hiloUniversityLessons.title,
337	              })
338	              .from(schema.hiloUniversityLessons)
339	              .where(
340	                and(
341	                  eq(schema.hiloUniversityLessons.status, 'archived'),
342	                  inArray(
343	                    schema.hiloUniversityLessons.id,
344	                    lessonIdsWithProgress,
345	                  ),
346	                ),
347	              )
348	          : [];
349	
350	      const inScopeLessons = [...publishedLessons, ...archivedLessons];
351	      const inScopeLessonIds = new Set(inScopeLessons.map((l) => l.id));
352	
353	      // Build (userId, lessonId) → progress lookup, filtered to in-scope lessons.
354	      const progressByPair = new Map<string, (typeof orgProgress)[number]>();
355	      for (const row of orgProgress) {
356	        if (!inScopeLessonIds.has(row.lessonId)) continue;
357	        progressByPair.set(`${row.userId}:${row.lessonId}`, row);
358	      }
359	
360	      const users: AnalyticsUserRow[] = usersInOrg.map((u) => ({
361	        userId: u.id,
362	        name: u.name,
363	        role: u.role,
364	        lessons: inScopeLessons.map((lesson) => {
365	          const prog = progressByPair.get(`${u.id}:${lesson.id}`);
366	          if (!prog) {
367	            return {
368	              lessonId: lesson.id,
369	              title: lesson.title,
370	              status: 'not_started' as const,
371	              percentComplete: 0,
372	              completedAt: null,
373	            };
374	          }
375	          const statusValue =
376	            prog.status === 'completed'
377	              ? ('completed' as const)
378	              : prog.status === 'not_started'
379	                ? ('not_started' as const)
380	                : ('in_progress' as const);
381	          return {
382	            lessonId: lesson.id,
383	            title: lesson.title,
384	            status: statusValue,
385	            percentComplete: prog.percentComplete,
386	            completedAt:
387	              prog.completedAt && prog.status === 'completed'
388	                ? prog.completedAt.toISOString()
389	                : null,
390	          };
391	        }),
392	      }));
393	
394	      return c.json({ users });
395	    } catch (err) {
396	      const structured = formatErrorForUser(err, {
397	        feature: 'HILU',
398	        actor: authUser.id,
399	      });
400	      return c.json(
401	        {
402	          error: structured.message,
403	          reference_id: structured.reference_id,
404	          retry_safe: structured.retry_safe,
405	        },
406	        500,
407	      );
408	    }
409	  },
410	);
