412	/** Coverage-by-role response shape. */
413	interface CoverageByRoleResponse {
414	  roleStats: Array<{
415	    role: string;
416	    lessonCount: number;
417	    suggestedTopics: string[];
418	    isUnderCovered?: boolean;
419	  }>;
420	  generatedAt: string | null;
421	  cacheStatus: 'fresh' | 'stale' | 'pending';
422	  summary?: string;
423	}
424	
425	/**
426	 * GET /hilo-university/admin-analytics/coverage-by-role
427	 *
428	 * Content-level (no `flight_school_id`). Super admin only.
429	 *
430	 * Behavior:
431	 *   - Reads the in-memory cache from the `universityCoverageGap` Inngest
432	 *     function (`src/lib/inngest/functions/university-coverage-gap.ts`).
433	 *   - Cache fresh (<24h) AND no `?refresh=1`  → 200 with cacheStatus='fresh'
434	 *   - Cache absent / stale / `?refresh=1`     → enqueue refresh + 202 pending
435	 *
436	 * The per-role `lessonCount` is always computed synchronously from the DB
437	 * so the count numbers stay correct even on a pending response. Only the
438	 * AI-derived `suggestedTopics` and `summary` are gated on the cache.
439	 */
440	hiloUniversityAnalyticsRoutes.get(
441	  '/hilo-university/admin-analytics/coverage-by-role',
442	  requireSuperAdmin(),
443	  async (c) => {
444	    const authUser = c.get('authUser') as AuthUser;
445	    const refresh = c.req.query('refresh') === '1';
446	
447	    try {
448	      // Synchronous DB aggregation — cheap, always accurate, no AI involved.
449	      const buckets = await aggregateLessonsByRole();
450	      const lessonCountByRole = new Map(
451	        buckets.map((b) => [b.role, b.lessons.length] as const),
452	      );
453	
454	      const snapshot = getCoverageGapCacheSnapshot();
455	      const cacheIsFresh = !refresh && isCoverageGapCacheFresh(snapshot);
456	
457	      if (cacheIsFresh && snapshot) {
458	        const aiByRole = new Map<
459	          string,
460	          (typeof snapshot.result.roleStats)[number]
461	        >(
462	          snapshot.result.roleStats.map(
463	            (entry) => [entry.role, entry] as const,
464	          ),
465	        );
466	        const roleStats = Array.from(lessonCountByRole.entries()).map(
467	          ([role, lessonCount]) => {
468	            const aiEntry = aiByRole.get(role);
469	            return {
470	              role,
471	              lessonCount,
472	              isUnderCovered: aiEntry?.isUnderCovered ?? false,
473	              suggestedTopics: aiEntry?.suggestedTopics ?? [],
474	            };
475	          },
476	        );
477	        const body: CoverageByRoleResponse = {
478	          roleStats,
479	          generatedAt: snapshot.generatedAt.toISOString(),
480	          cacheStatus: 'fresh',
481	          summary: snapshot.result.summary,
482	        };
483	        return c.json(body, 200);
484	      }
485	
486	      // Stale, missing, or forced-refresh — enqueue and return pending.
487	      await inngest.send({
488	        name: 'university/coverage.refresh',
489	        data: {
490	          reason: refresh ? 'manual_refresh' : 'on_demand',
491	          requestedByUserId: authUser.id,
492	        },
493	      });
494	
495	      if (refresh) {
496	        c.header('X-Hilu-Coverage-Refresh', '1');
497	      }
498	
499	      const pendingRoleStats = Array.from(lessonCountByRole.entries()).map(
500	        ([role, lessonCount]) => ({
501	          role,
502	          lessonCount,
503	          suggestedTopics: [] as string[],
504	        }),
505	      );
506	      const body: CoverageByRoleResponse = {
507	        roleStats: pendingRoleStats,
508	        generatedAt: snapshot?.generatedAt.toISOString() ?? null,
509	        cacheStatus: 'pending',
510	      };
511	      return c.json(body, 202);
512	    } catch (err) {
513	      const structured = formatErrorForUser(err, {
514	        feature: 'HILU',
515	        actor: authUser.id,
516	      });
517	      return c.json(
518	        {
519	          error: structured.message,
520	          reference_id: structured.reference_id,
521	          retry_safe: structured.retry_safe,
522	        },
523	        500,
524	      );
525	    }
526	  },
527	);
