1068	/** Fire the training.lesson_completed workflow trigger. Non-blocking. */
1069	async function fireLessonCompletedTrigger(
1070	  studentId: string,
1071	  courseId: string,
1072	  lessonId: string,
1073	  completedCount: number,
1074	): Promise<void> {
1075	  try {
1076	    const { triggerWorkflowsForEvent } = await import(
1077	      '@/lib/automations/triggerWorkflow'
1078	    );
1079	
1080	    // Resolve student info
1081	    const [student] = await db
1082	      .select({
1083	        name: schema.users.name,
1084	        phone: schema.users.phone,
1085	        flightSchoolId: schema.users.flightSchoolId,
1086	        locationId: schema.users.locationId,
1087	      })
1088	      .from(schema.users)
1089	      .where(eq(schema.users.id, studentId))
1090	      .limit(1);
1091	    if (!student) return;
1092	
1093	    // Resolve course and lesson details
1094	    const [course] = await db
1095	      .select({ title: schema.lmsCourses.title })
1096	      .from(schema.lmsCourses)
1097	      .where(eq(schema.lmsCourses.id, courseId))
1098	      .limit(1);
1099	
1100	    const [lesson] = await db
1101	      .select({
1102	        title: schema.lmsLessons.title,
1103	        sortOrder: schema.lmsLessons.sortOrder,
1104	      })
1105	      .from(schema.lmsLessons)
1106	      .where(
1107	        and(
1108	          eq(schema.lmsLessons.courseId, courseId),
1109	          eq(schema.lmsLessons.id, lessonId),
1110	        ),
1111	      )
1112	      .limit(1);
1113	
1114	    // Count total lessons in course for completion percentage
1115	    const allLessons = await db
1116	      .select({ id: schema.lmsLessons.id })
1117	      .from(schema.lmsLessons)
1118	      .where(eq(schema.lmsLessons.courseId, courseId));
1119	    const totalLessons = allLessons.length;
1120	    const courseCompletionPct =
1121	      totalLessons > 0 ? Math.round((completedCount / totalLessons) * 100) : 0;
1122	
1123	    // Resolve location name
1124	    let locationName: string | null = null;
1125	    if (student.locationId) {
1126	      const [loc] = await db
1127	        .select({ name: schema.locations.name })
1128	        .from(schema.locations)
1129	        .where(eq(schema.locations.id, student.locationId))
1130	        .limit(1);
1131	      if (loc) locationName = loc.name;
1132	    }
1133	
1134	    await triggerWorkflowsForEvent(
1135	      'training.lesson_completed',
1136	      {
1137	        eventId: `lesson_completed:${studentId}:${lessonId}`,
1138	        locationId: student.locationId ?? '',
1139	        flightSchoolId: student.flightSchoolId,
1140	        studentId,
1141	        studentName: student.name,
1142	        studentPhone: student.phone ?? null,
1143	        locationName,
1144	        courseName: course?.title ?? null,
1145	        lessonName: lesson?.title ?? null,
1146	        lessonNumber: lesson?.sortOrder ?? null,
1147	        courseCompletionPct,
1148	      },
1149	      student.flightSchoolId,
1150	      student.locationId ?? '',
1151	    );
1152	  } catch (err) {
1153	    console.error('[LMS] Error firing training.lesson_completed trigger:', err);
1154	  }
1155	}
