44	  const color =
45	    value >= 80
46	      ? 'bg-emerald-500'
47	      : value >= 50
48	        ? 'bg-teal-500'
49	        : value >= 25
50	          ? 'bg-amber-500'
51	          : 'bg-slate-300';
52	  return (
53	    <div className={`w-full bg-slate-100 rounded-full ${h} overflow-hidden`}>
54	      <motion.div
55	        className={`${h} rounded-full ${color}`}
56	        initial={{ width: 0 }}
57	        animate={{ width: `${Math.min(value, 100)}%` }}
58	        transition={{ duration: 0.8, ease: 'easeOut' }}
59	      />
60	    </div>
61	  );
62	}
