41	function EmbedPlayer({ url, type }: { url: string; type: string | null }) {
42	  if (!url) {
43	    return (
44	      <div className="aspect-video w-full bg-muted rounded-lg flex items-center justify-center">
45	        <p className="text-muted-foreground text-sm">No video available</p>
46	      </div>
47	    );
48	  }
49	
50	  const isYouTube =
51	    type === 'youtube' ||
52	    url.includes('youtube.com') ||
53	    url.includes('youtu.be');
54	  const isVimeo = type === 'vimeo' || url.includes('vimeo.com');
55	  const isLoom = type === 'loom' || url.includes('loom.com');
56	
57	  const getEmbedUrl = () => {
58	    if (isYouTube) {
59	      const match =
60	        url.match(/[?&]v=([^&]+)/) ?? url.match(/youtu\.be\/([^?]+)/);
61	      const videoId = match?.[1];
62	      if (videoId) return `https://www.youtube.com/embed/${videoId}`;
63	    }
64	    if (isVimeo) {
65	      const match = url.match(/vimeo\.com\/(\d+)/);
66	      const videoId = match?.[1];
67	      if (videoId) return `https://player.vimeo.com/video/${videoId}`;
68	    }
69	    if (isLoom) {
70	      const match = url.match(/loom\.com\/(?:share|embed)\/([a-f0-9]+)/i);
71	      const videoId = match?.[1];
72	      if (videoId) return `https://www.loom.com/embed/${videoId}`;
73	    }
74	    return url;
75	  };
76	
77	  return (
78	    <div className="aspect-video w-full rounded-lg overflow-hidden bg-black">
79	      <iframe
80	        src={getEmbedUrl()}
81	        title="Lesson video"
82	        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
83	        allowFullScreen
84	        className="h-full w-full"
85	      />
86	    </div>
87	  );
88	}
